import{bQ as r,aL as d,u as o,G as n}from"./chunks/framework.DaEK0KQB.js";const b=JSON.parse('{"title":"3X-UI 面板管理脚本完全指南","description":"","frontmatter":{"title":"3X-UI 面板管理脚本完全指南","date":"2026-03-22T19:49:32.000Z","permalink":"/pages/d0674a/","categories":["更多","AI"],"tags":[null]},"headers":[],"relativePath":"更多/AI/02.3X-UI 面板管理脚本完全指南.md","filePath":"更多/AI/02.3X-UI 面板管理脚本完全指南.md","lastUpdated":1785303693000}'),s={name:"更多/AI/02.3X-UI 面板管理脚本完全指南.md"};function e(a,t,g,h,l,i){return d(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_3x-ui-面板管理脚本完全指南" tabindex="-1">3X-UI 面板管理脚本完全指南 <a class="header-anchor" href="#_3x-ui-面板管理脚本完全指南" aria-label="Permalink to &quot;3X-UI 面板管理脚本完全指南&quot;">​</a></h1><p>本文档详细介绍了 <strong>3X-UI Panel Management Script</strong> 的所有功能选项、使用场景及注意事项。适用于基于 Ubuntu/Debian/CentOS 等系统的服务器管理。</p><blockquote><p><strong>当前状态示例</strong>:</p><ul><li><code>Panel state</code>: Running (面板运行中)</li><li><code>Start automatically</code>: Yes (已开启开机自启)</li><li><code>xray state</code>: Running (核心运行中)</li></ul></blockquote><hr><h2 id="_1-基础控制" tabindex="-1">1. 基础控制 <a class="header-anchor" href="#_1-基础控制" aria-label="Permalink to &quot;1. 基础控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th></tr></thead><tbody><tr><td><strong>0</strong></td><td><strong>Exit Script</strong></td><td><strong>退出脚本</strong>。结束当前管理界面，返回到 Linux 命令行提示符。</td></tr></tbody></table><hr><h2 id="_2-安装与维护" tabindex="-1">2. 安装与维护 <a class="header-anchor" href="#_2-安装与维护" aria-label="Permalink to &quot;2. 安装与维护&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th><th>注意事项</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong>Install</strong></td><td><strong>全新安装</strong>。在从未安装过 3X-UI 的服务器上执行此操作。</td><td>若已安装，请勿随意点击，以免覆盖配置。</td></tr><tr><td><strong>2</strong></td><td><strong>Update</strong></td><td><strong>更新面板</strong>。将 3X-UI 程序和核心升级到最新版本。</td><td>建议定期更新以修复漏洞。<strong>更新前建议备份数据库</strong>。</td></tr><tr><td><strong>3</strong></td><td><strong>Update Menu</strong></td><td><strong>更新菜单脚本</strong>。仅刷新管理脚本本身，不更新面板核心。</td><td>当菜单显示异常或需要最新管理功能时使用。</td></tr><tr><td><strong>4</strong></td><td><strong>Legacy Version</strong></td><td><strong>切换旧版</strong>。回退到旧版本或原版 X-UI。</td><td>仅在新版出现严重兼容性故障时使用。</td></tr><tr><td><strong>5</strong></td><td><strong>Uninstall</strong></td><td><strong>彻底卸载</strong>。删除面板、核心、配置文件及数据库。</td><td>⚠️ <strong>高危操作</strong>：所有节点数据和设置将丢失，操作前务必备份！</td></tr></tbody></table><hr><h2 id="_3-账户与配置重置" tabindex="-1">3. 账户与配置重置 <a class="header-anchor" href="#_3-账户与配置重置" aria-label="Permalink to &quot;3. 账户与配置重置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th><th>是否需要重启</th></tr></thead><tbody><tr><td><strong>6</strong></td><td><strong>Reset Username &amp; Password</strong></td><td><strong>重置登录凭证</strong>。修改面板的用户名和密码。</td><td>❌ 否 (立即生效)</td></tr><tr><td><strong>7</strong></td><td><strong>Reset Web Base Path</strong></td><td><strong>重置访问路径</strong>。修改或清空面板 URL 的后缀路径 (如 <code>/secret</code>)。</td><td>✅ 是 (需重启面板)</td></tr><tr><td><strong>8</strong></td><td><strong>Reset Settings</strong></td><td><strong>恢复出厂设置</strong>。清空所有自定义配置，回到初始状态。</td><td>⚠️ <strong>高危</strong>：会清除用户数据，慎用！</td></tr><tr><td><strong>9</strong></td><td><strong>Change Port</strong></td><td><strong>修改面板端口</strong>。更改网页管理的监听端口 (默认通常为 54321)。</td><td>✅ 是 (需重启面板)</td></tr></tbody></table><hr><h2 id="_4-信息查看" tabindex="-1">4. 信息查看 <a class="header-anchor" href="#_4-信息查看" aria-label="Permalink to &quot;4. 信息查看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th></tr></thead><tbody><tr><td><strong>10</strong></td><td><strong>View Current Settings</strong></td><td><strong>查看当前设置</strong>。显示面板地址、端口、用户名、路径、数据库位置等关键信息。</td></tr></tbody></table><hr><h2 id="_5-服务运行控制" tabindex="-1">5. 服务运行控制 <a class="header-anchor" href="#_5-服务运行控制" aria-label="Permalink to &quot;5. 服务运行控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>11</strong></td><td><strong>Start</strong></td><td><strong>启动面板</strong>。手动启动 3X-UI 服务。</td><td>服务意外停止时。</td></tr><tr><td><strong>12</strong></td><td><strong>Stop</strong></td><td><strong>停止面板</strong>。手动停止 3X-UI 服务。</td><td>临时维护或调试时。</td></tr><tr><td><strong>13</strong></td><td><strong>Restart</strong></td><td><strong>重启面板</strong>。重启 3X-UI 网页管理服务。</td><td>修改面板端口、路径后生效。</td></tr><tr><td><strong>14</strong></td><td><strong>Restart Xray</strong></td><td><strong>重启核心</strong>。仅重启 Xray 流量核心，不影响网页面板。</td><td><strong>添加/修改节点后必须执行</strong>，使配置生效。</td></tr><tr><td><strong>15</strong></td><td><strong>Check Status</strong></td><td><strong>检查状态</strong>。查看面板和核心的运行状态及开机自启状态。</td><td>排查服务是否正常运行。</td></tr></tbody></table><hr><h2 id="_6-日志与自动化" tabindex="-1">6. 日志与自动化 <a class="header-anchor" href="#_6-日志与自动化" aria-label="Permalink to &quot;6. 日志与自动化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th></tr></thead><tbody><tr><td><strong>16</strong></td><td><strong>Logs Management</strong></td><td><strong>日志管理</strong>。查看面板日志、Xray 核心日志，或清空日志文件。</td></tr><tr><td><strong>17</strong></td><td><strong>Enable Autostart</strong></td><td><strong>开启自启</strong>。设置服务器重启后自动运行面板和核心。</td></tr><tr><td><strong>18</strong></td><td><strong>Disable Autostart</strong></td><td><strong>关闭自启</strong>。取消开机自动运行。</td></tr></tbody></table><hr><h2 id="_7-安全与网络优化" tabindex="-1">7. 安全与网络优化 <a class="header-anchor" href="#_7-安全与网络优化" aria-label="Permalink to &quot;7. 安全与网络优化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th></tr></thead><tbody><tr><td><strong>19</strong></td><td><strong>SSL Certificate Management</strong></td><td><strong>SSL 证书管理</strong>。自动申请 (Let&#39;s Encrypt)、续签或上传 HTTPS 证书。</td></tr><tr><td><strong>20</strong></td><td><strong>Cloudflare SSL Certificate</strong></td><td><strong>CF 证书管理</strong>。专门配置 Cloudflare 边缘证书。</td></tr><tr><td><strong>21</strong></td><td><strong>IP Limit Management</strong></td><td><strong>IP 限制管理</strong>。限制每个用户允许同时在线的 IP 数量。</td></tr><tr><td><strong>22</strong></td><td><strong>Firewall Management</strong></td><td><strong>防火墙管理</strong>。一键管理服务器防火墙 (如 UFW)，放行或阻断端口。</td></tr><tr><td><strong>23</strong></td><td><strong>SSH Port Forwarding</strong></td><td><strong>SSH 端口转发</strong>。配置本地隧道映射。</td></tr></tbody></table><hr><h2 id="_8-系统性能与工具" tabindex="-1">8. 系统性能与工具 <a class="header-anchor" href="#_8-系统性能与工具" aria-label="Permalink to &quot;8. 系统性能与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>功能名称</th><th>详细说明</th></tr></thead><tbody><tr><td><strong>24</strong></td><td><strong>Enable BBR</strong></td><td><strong>开启 BBR 加速</strong>。启用 Google BBR 拥塞控制算法。</td></tr><tr><td><strong>25</strong></td><td><strong>Update Geo Files</strong></td><td><strong>更新地理库</strong>。更新 <code>geosite.dat</code> 和 <code>geoip.dat</code>。</td></tr><tr><td><strong>26</strong></td><td><strong>Speedtest by Ookla</strong></td><td><strong>网速测试</strong>。在服务器端运行专业测速。</td></tr></tbody></table><hr><h2 id="_9-常用操作速查表" tabindex="-1">9. 常用操作速查表 <a class="header-anchor" href="#_9-常用操作速查表" aria-label="Permalink to &quot;9. 常用操作速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想做什么？</th><th>推荐选项</th><th>备注</th></tr></thead><tbody><tr><td><strong>忘了密码/端口</strong></td><td><code>10</code></td><td>查看当前设置</td></tr><tr><td><strong>修改密码</strong></td><td><code>6</code></td><td>立即生效</td></tr><tr><td><strong>刚添加了新节点</strong></td><td><code>14</code></td><td>重启 Xray 核心使配置生效</td></tr><tr><td><strong>服务器刚重装好</strong></td><td><code>24</code> -&gt; <code>6</code> -&gt; <code>19</code></td><td>开加速 -&gt; 改密码 -&gt; 配证书</td></tr><tr><td><strong>节点连不上/报错</strong></td><td><code>16</code></td><td>查看日志分析原因</td></tr><tr><td><strong>面板打不开</strong></td><td><code>15</code> -&gt; <code>22</code></td><td>查状态 -&gt; 查防火墙</td></tr><tr><td><strong>定期维护</strong></td><td><code>2</code> -&gt; <code>25</code></td><td>更新面板 -&gt; 更新地理库</td></tr></tbody></table><hr><h3 id="💡-温馨提示" tabindex="-1">💡 温馨提示 <a class="header-anchor" href="#💡-温馨提示" aria-label="Permalink to &quot;💡 温馨提示&quot;">​</a></h3><ul><li><strong>备份习惯</strong>：在进行 <code>Update</code> (更新) 或 <code>Uninstall</code> (卸载) 等操作前，建议先备份数据库文件 (通常位于 <code>/etc/x-ui/x-ui.db</code>)。</li><li><strong>安全性</strong>：生产环境中，务必修改默认端口 (<code>9</code>)，设置强密码 (<code>6</code>)，并配置 SSL 证书 (<code>19</code>)。</li><li><strong>日志先行</strong>：遇到任何连接问题，第一反应应该是查看日志 (<code>16</code>)，而不是盲目重启。</li></ul>',33)])])}const _=r(s,[["render",e]]);export{b as __pageData,_ as default};
